import{c as t,Q as s,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const l="/assets/Add%E7%AE%97%E5%AD%90%E5%AE%9E%E7%8E%B0%E6%B5%81%E7%A8%8B-47.By6RT0t5.png",p="/assets/Matmul%E7%9F%A9%E9%98%B5%E4%B9%98%E7%A4%BA%E6%84%8F%E5%9B%BE-48.CIEJkaVJ.png",i="data:image/png;base64,",o="/assets/zh-cn_image_0000001425411698.D5xAPUSt.png",c="/assets/%E7%BC%96%E7%A8%8B%E8%8C%83%E5%BC%8F.KytWnzjV.png",r="/assets/%E7%BC%96%E7%A8%8B%E8%8C%83%E5%BC%8F-49.TyusC0pg.png",u="/assets/matmul%E7%AE%97%E5%AD%90%E8%AE%A1%E7%AE%97%E6%B5%81%E7%A8%8B%E5%9B%BE-50.BUPbVI6I.png",C=JSON.parse('{"title":"算子实现","description":"","frontmatter":{},"headers":[{"level":1,"title":"算子实现","slug":"算子实现"},{"level":2,"title":"算子分析","slug":"算子分析"},{"level":2,"title":"数据流分析","slug":"数据流分析"},{"level":2,"title":"Tiling策略设计","slug":"tiling策略设计"},{"level":2,"title":"算子实现","slug":"算子实现"}],"relativePath":"guide/算子实践参考/SIMD算子实现/融合算子编程/CV融合/算子实现.md","filePath":"guide/算子实践参考/SIMD算子实现/融合算子编程/CV融合/算子实现.md"}'),g={name:"guide/算子实践参考/SIMD算子实现/融合算子编程/CV融合/算子实现.md"};function d(m,a,b,h,A,y){return s(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="算子实现" tabindex="-1">算子实现 <a class="header-anchor" href="#算子实现" aria-label="Permalink to &quot;算子实现&quot;">​</a></h1><p>下文将以Matmul+LeakyRelu融合算子的实现为例，介绍Mix融合算子的设计和实现流程。</p><p>算子的设计过程分为<strong>算子分析、数据流分析、Tiling策略设计</strong>三部分。</p><h2 id="算子分析" tabindex="-1">算子分析 <a class="header-anchor" href="#算子分析" aria-label="Permalink to &quot;算子分析&quot;">​</a></h2><p>算子分析是指明确算子的数学表达式、输入、输出，核函数的名称等信息。</p><ol><li><p>明确算子的数学表达式及计算逻辑。该算子的计算逻辑为，先进行一个矩阵乘操作，然后将矩阵乘的结果与一个alpha参数进行LeakyRelu操作。数学表达式如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>c = LeakyRelu(a * b + bias, alpha);</span></span></code></pre></div></li><li><p>明确输入和输出。</p><ul><li>Matmul+LeakyRelu算子输入为a、b、bias，输出为c。alpha作为激活函数LeakyRelu的系数，为固定值，可以在算子实现中直接使用常数值参与计算。</li><li>本样例中算子输入a、b支持的数据类型为half（float16），算子输入bias支持的数据类型为float32，算子输出c的数据类型为float32。</li><li>输入矩阵a的形状为[M，K]，输入矩阵b的形状为[K, N]，输出矩阵c的形状为[M，N]，输入bias的形状为[1, N]。</li><li>算子输入输出支持的数据格式为：ND。</li></ul></li><li><p>确定核函数名称和参数。</p><ul><li>您可以自定义核函数名称，本样例中核函数命名为matmul_leakyrelu_custom。</li><li>根据对算子输入输出的分析，确定核函数的参数a，b，bias，c；a，b, bias为输入在Global Memory上的内存地址，c为输出在Global Memory上的内存地址。</li></ul></li></ol><p>通过以上分析，得到Ascend C Matmul+LeakyRelu算子的设计规格如下：</p><ul><li><p>算子类型（OpType）：MATMUL_LEAKYRELU</p></li><li><p>算子输入输出：</p><p><strong>表 1</strong> MATMUL_LEAKYRELU算子输入输出规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;name&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;shape&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;data type&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;format&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;a（输入）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;[M, K]&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;half&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;b（输入）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;[K, N]&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;half&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;bias（输入）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;[1, N]&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float32&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;z（输出）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;[M, N]&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float32&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p>核函数名称：matmul_leakyrelu_custom</p></li></ul><h2 id="数据流分析" tabindex="-1">数据流分析 <a class="header-anchor" href="#数据流分析" aria-label="Permalink to &quot;数据流分析&quot;">​</a></h2><p>进行算子的数据流分析：数据流向为在Cube核上完成Matmul计算后将数据搬运至Vector核进行LeakyRelu计算。根据上述数据流并结合融合算子的编程范式，规划并行的流水任务。如下图所示：</p><p><img src="'+l+'" alt=""></p><ol><li><p>将输入数据从Global Memory搬运到Cube核。</p></li><li><p>进行Matmul内部的计算，计算公式和计算示意图如下：</p><p>注：bias的shape为[1, N]，对A*B结果矩阵的每一行都采用该bias进行偏置。</p><p><strong>图 1</strong> Matmul矩阵乘示意图<br><img src="'+p+'" alt="" title="Matmul矩阵乘示意图-48"></p></li><li><p>将Matmul的计算结果搬运到Vector核。</p></li><li><p>进行Vector矢量计算，该样例中进行LeakyReLU计算。</p><p>Leaky ReLU（带泄露线性整流函数）激活函数，是人工神经网络中一种常用的激活函数，其数学表达式和函数图像如下所示：</p><p><img src="'+i+'" alt=""></p><p><img src="'+o+'" alt=""></p></li><li><p>将输出结果搬运到Global Memory。</p></li></ol><p>前三步的内容都封装在Matmul高阶API内，本样例中可以简化为3个stage。如下图所示：</p><p><img src="'+c+'" alt=""></p><p>根据上述分析，明确实现过程中会使用到<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Matmul-Kernel%E4%BE%A7%E6%8E%A5%E5%8F%A3.md" target="_blank" rel="noreferrer">Matmul高阶API</a>接口，<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/LeakyRelu.md" target="_blank" rel="noreferrer">LeakyRelu Vector计算接口</a>、<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DataCopy.md" target="_blank" rel="noreferrer">DataCopy</a>、<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/EnQue.md" target="_blank" rel="noreferrer">EnQue</a>、<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DeQue.md" target="_blank" rel="noreferrer">DeQue</a>接口。</p><h2 id="tiling策略设计" tabindex="-1">Tiling策略设计 <a class="header-anchor" href="#tiling策略设计" aria-label="Permalink to &quot;Tiling策略设计&quot;">​</a></h2><p>Tiling策略的设计主要包括多核切分和核内切分策略。</p><ul><li>多核切分: 根据当前核数，对输入shape的M, K, N进行多核切分，得到单核内shape大小singleCoreM, singleCoreK, singleCoreN。</li><li>核内切分: 根据Local Memory的大小约束，对单核内的shape大小进一步切分，得到A、B、C矩阵参与一次矩阵乘指令的shape大小baseM, baseN, baseK。切分时需要注意：GetTensorC的结果如果放在LocalMemory（UB）上，需要注意，baseM * baseN的大小不能超出UB的限制。</li></ul><p>切分策略示意图如下，更多切分策略相关原理请参考<a href="./../../矩阵编程（高阶API）/基础知识.html">数据分块（Tiling）</a>。</p><p><img src="'+r+'" alt=""></p><h2 id="算子实现-1" tabindex="-1">算子实现 <a class="header-anchor" href="#算子实现-1" aria-label="Permalink to &quot;算子实现&quot;">​</a></h2><p>在<a href="./../../矩阵编程（高阶API）/矩阵编程（高阶API）.html">矩阵编程章节</a>，我们得知Ascend C提供一组Matmul高阶API，封装了常用的切分和数据搬运、计算的算法逻辑，方便用户快速实现Matmul矩阵乘法的运算操作。融合算子中矩阵编程部分的实现与之类似，开发者在host侧通过调用API自动获取Tiling参数，该参数传递到kernel侧后，在初始化操作时传入，通过几个简单的API即可完成矩阵乘操作。再结合上文的融合算子的编程范式，融合算子实现的步骤如下。完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/00_introduction/03_fusion_operation/matmul_leakyrelu_high_level_api" target="_blank" rel="noreferrer">MatmulLeakyRelu</a>。</p><p><img src="'+u+`" alt=""></p><p>kernel侧实现的代码框架如下，在完成Matmul对象的初始化、左矩阵A、右矩阵B、Bias的设置后，通过单次Iterate叠加while循环的方式完成后续的Matmul计算、LeakyRelu计算、CopyOut流程。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename aType, typename bType, typename cType, typename biasType&gt;</span></span>
<span class="line"><span>__aicore__ inline void MatmulLeakyKernel&lt;aType, bType, cType, biasType&gt;::Process(){</span></span>
<span class="line"><span>    uint32_t computeRound = 0;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    // 设置Matmul的输入（包括左矩阵、右矩阵、bias）</span></span>
<span class="line"><span>    matmulObj.SetTensorA(aGlobal);</span></span>
<span class="line"><span>    matmulObj.SetTensorB(bGlobal);</span></span>
<span class="line"><span>    matmulObj.SetBias(biasGlobal);</span></span>
<span class="line"><span>    // 调用matmul iterate获取一块[baseM, baseN]的计算结果</span></span>
<span class="line"><span>    while (matmulObj.template Iterate&lt;true&gt;())</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        MatmulCompute();</span></span>
<span class="line"><span>        LeakyReluCompute();</span></span>
<span class="line"><span>        CopyOut(computeRound);</span></span>
<span class="line"><span>        computeRound++;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    matmulObj.End();</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// kernel入口函数，mix场景，AIC:AIV=1:2</span></span>
<span class="line"><span>__global__ __mix__(1, 2) void matmul_leakyrelu_custom(GM_ADDR a, GM_ADDR b, GM_ADDR bias, GM_ADDR c,</span></span>
<span class="line"><span>                                                      __kfc_workspace__ GM_ADDR workspace, AscendC::tiling::TCubeTiling tiling)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::TPipe pipe;</span></span>
<span class="line"><span>    MatmulLeakyKernel&lt;half, half, float, float&gt; matmulLeakyKernel;</span></span>
<span class="line"><span>    matmulLeakyKernel.Init(a, b, bias, c, workspace, tiling, &amp;pipe);</span></span>
<span class="line"><span>    // Matmul对象初始化</span></span>
<span class="line"><span>    REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), matmulLeakyKernel.matmulObj, &amp;matmulLeakyKernel.tiling);</span></span>
<span class="line"><span>    matmulLeakyKernel.Process();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Matmul计算、LeakyRelu计算、CopyOut的具体实现代码如下：</p><ol><li><p>Matmul计算：</p><ol><li><p>在Cube核上，进行Matmul内部的计算。</p></li><li><p>将Matmul的计算结果搬运到Vector核。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename aType, typename bType, typename cType, typename biasType&gt;</span></span>
<span class="line"><span>__aicore__ inline void MatmulLeakyKernel&lt;aType, bType, cType, biasType&gt;::Process(){</span></span>
<span class="line"><span>    uint32_t computeRound = 0;</span></span>
<span class="line"><span>    // ...</span></span>
<span class="line"><span>    // 调用matmul iterate获取一块[baseM, baseN]的计算结果</span></span>
<span class="line"><span>    while (matmulObj.template Iterate&lt;true&gt;())</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        MatmulCompute();</span></span>
<span class="line"><span>        // ...</span></span>
<span class="line"><span>        computeRound++;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    matmulObj.End();</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>template&lt;typename aType, typename bType, typename cType, typename biasType&gt;</span></span>
<span class="line"><span>__aicore__ inline void MatmulLeakyKernel&lt;aType, bType, cType, biasType&gt;::MatmulCompute(){</span></span>
<span class="line"><span>    reluOutLocal = reluOutQueue_.AllocTensor&lt;cType&gt;();</span></span>
<span class="line"><span>    // 调用GetTensorC将Matmul的计算结果搬运到Vector核。</span></span>
<span class="line"><span>    matmulObj.template GetTensorC&lt;true&gt;(reluOutLocal, false, true);</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ol></li><li><p>LeakyRelu计算。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 调用LeakyRelu接口进行计算</span></span>
<span class="line"><span>template&lt;typename aType, typename bType, typename cType, typename biasType&gt;</span></span>
<span class="line"><span>__aicore__ inline void MatmulLeakyKernel&lt;aType, bType, cType, biasType&gt;::LeakyReluCompute(){</span></span>
<span class="line"><span>    AscendC::LeakyRelu(reluOutLocal, reluOutLocal, (cType)alpha, tiling.baseM * tiling.baseN);</span></span>
<span class="line"><span>    reluOutQueue_.EnQue(reluOutLocal);</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>CopyOut，将输出结果搬运到Global Memory。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 将结果搬出到GM</span></span>
<span class="line"><span>template&lt;typename aType, typename bType, typename cType, typename biasType&gt;</span></span>
<span class="line"><span>__aicore__ inline void MatmulLeakyKernel&lt;aType, bType, cType, biasType&gt;::CopyOut(uint32_t count){</span></span>
<span class="line"><span>    reluOutQueue_.DeQue&lt;cType&gt;();</span></span>
<span class="line"><span>    const uint32_t roundM = tiling.singleCoreM / tiling.baseM;</span></span>
<span class="line"><span>    const uint32_t roundN = tiling.singleCoreN / tiling.baseN;</span></span>
<span class="line"><span>    uint32_t startOffset = (count % roundM * tiling.baseM * tiling.N + count / roundM * tiling.baseN);</span></span>
<span class="line"><span>    AscendC::DataCopyParams copyParam = {(uint16_t)tiling.baseM,</span></span>
<span class="line"><span>        (uint16_t)(tiling.baseN * sizeof(cType) / DEFAULT_C0_SIZE), 0,</span></span>
<span class="line"><span>        (uint16_t)((tiling.N - tiling.baseN) * sizeof(cType) / DEFAULT_C0_SIZE)};</span></span>
<span class="line"><span>    AscendC::DataCopy(cGlobal[startOffset], reluOutLocal, copyParam);</span></span>
<span class="line"><span>    reluOutQueue_.FreeTensor(reluOutLocal);</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ol><p>host侧实现GenerateTiling函数，在该函数中自动获取Tiling参数，关键步骤介绍如下：</p><ol><li><p><strong>创建Tiling对象</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();</span></span>
<span class="line"><span>matmul_tiling::MultiCoreMatmulTiling tilingApi(ascendcPlatform);</span></span></code></pre></div><p>创建对象时需要传入硬件平台信息，硬件平台信息可以通过GetInstance获取。</p></li><li><p><strong>设置A、B、Bias的数据类型和格式。</strong></p><p>设置示例如下，关于TPosition的详细内容请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/TPosition.md" target="_blank" rel="noreferrer">TPosition</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tilingApi.SetAType(TPosition::GM, CubeFormat::ND, DataType::DT_FLOAT16, false);</span></span>
<span class="line"><span>tilingApi.SetBType(TPosition::GM, CubeFormat::ND, DataType::DT_FLOAT16, false);</span></span>
<span class="line"><span>tilingApi.SetCType(TPosition::GM, CubeFormat::ND, DataType::DT_FLOAT);</span></span>
<span class="line"><span>tilingApi.SetBiasType(TPosition::GM, CubeFormat::ND, DataType::DT_FLOAT);</span></span></code></pre></div></li><li><p><strong>设置矩阵shape信息。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tilingApi.SetOrgShape(M, N, K);</span></span>
<span class="line"><span>tilingApi.SetShape(M, N, K);</span></span></code></pre></div></li><li><p><strong>设置可用空间大小信息。</strong></p><p><strong>设置Matmul计算时可用的L1 Buffer/L0C Buffer/Unified Buffer空间大小，-1表示AI处理器对应Buffer的大小。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tilingApi.SetBufferSpace(-1, -1, -1);</span></span></code></pre></div></li><li><p><strong>按需设置其他参数，比如设置bias参与计算，设置Matmul计算方向为M轴优先。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tilingApi.SetBias(true);</span></span>
<span class="line"><span>tilingApi.SetTraverse(matmul_tiling::MatrixTraverse::FIRSTM);</span></span></code></pre></div></li><li><p><strong>获取Tiling参数。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::tiling::TCubeTiling tilingData;</span></span>
<span class="line"><span>int64_t res = tilingApi.GetTiling(tilingData);</span></span>
<span class="line"><span>if (res == -1) {</span></span>
<span class="line"><span>    std::cout &lt;&lt; &quot;gen tiling failed&quot; &lt;&lt; std::endl;</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>Tiling参数的序列化保存等其他操作。</p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p></p><ul><li>特别的对于多核场景，需要通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetDim.md" target="_blank" rel="noreferrer">SetDim</a>接口设置Matmul计算所用的核数，MIX模式（包含矩阵计算和矢量计算）的设置规则如下： <ul><li><a href="./../../../../编程指南/硬件实现/基本架构.html#li188191010204418">分离模式</a>：Matmul API都是从AIV侧发起的，调用Iterate计算时在AIV侧只会起到通知的作用，通知AIC去做矩阵计算，计算完成后AIC告知AIV计算完成。这个架构下，SetBlockDim设置为实际计算会用到的AI Core（AIC、AIV组合）的数量，SetDim设置为实际计算会用到的AIV的数量。例如，SetBlockDim时可以设置为20，启动20个AI Core（AIC AIV的组合），SetDim设置为40，表示按照40个AIV进行切分。</li><li><a href="./../../../../编程指南/硬件实现/基本架构.html#li1414517184416">耦合模式</a>：SetBlockDim加载的核数就是Matmul API实际计算会用到的核数，SetDim和SetBlockDim设置的值是一样的。</li></ul></li><li>Matmul高阶API内部实现时需要使用系统workspace，开发者需要： <ul><li>在host侧Tiling实现时，设置总的workspace的数值大小（包含用户workspace和系统workspace），workspace空间由框架来申请并管理。系统workspace的空间大小通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/GetLibApiWorkSpaceSize.md" target="_blank" rel="noreferrer">GetLibApiWorkSpaceSize</a>获取。<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>size_t userWorkspaceSize = 0;</span></span>
<span class="line"><span>size_t systemWorkspaceSize = ascendcPlatform.GetLibApiWorkSpaceSize();</span></span>
<span class="line"><span>size_t workspaceSize = userWorkspaceSize + systemWorkspaceSize;</span></span></code></pre></div></li><li>若算子工程不是<a href="./../../../../编程指南/附录/工程化算子开发/概述.html">自定义算子工程</a>，也不是带有<a href="./../../../../编程指南/附录/基于样例工程完成Kernel直调.html#table481718169817">HAVE_WORKSPACE</a>编译宏的Kernel直调算子工程，kernel侧需要在Matmul初始化前，通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetSysWorkSpace.md" target="_blank" rel="noreferrer">SetSysWorkSpace</a>设置系统workspace。<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 使用Matmul时必须设置workspace空间    </span></span>
<span class="line"><span>SetSysWorkspace(workspace);</span></span>
<span class="line"><span>if (GetSysWorkSpacePtr() == nullptr) {</span></span>
<span class="line"><span>    return;</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ul></li><li>上文介绍的实现方法，AIC侧和AIV侧的代码隔离和核间同步由框架来完成，开发者无需关心。除该方法外，开发者也可以选择底层编码的方式在分离模式下实现融合算子，这种方式将更加灵活。采用底层编码方式时，需要注意以下几点： <ul><li>通过<a href="./../../../../编程指南/语言扩展层/SIMD-BuiltIn关键字.html#li19530175294118">ASCEND_IS_AIV和ASCEND_IS_AIC</a>实现AIV和AIC代码之间的隔离。</li><li>自行实现AIC和AIV核之间的同步：比如Matmul + LeakyRelu算子样例中，需要确保在AIC完成矩阵计算后，AIV再进行LeakyRelu的计算。</li><li>使用高阶API Matmul时需要设置ASCENDC_CUBE_ONLY，表示仅在AIC侧调用Matmul API。</li><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/%E8%AE%BE%E7%BD%AEKernel%E7%B1%BB%E5%9E%8B.md" target="_blank" rel="noreferrer">设置Kernel类型接口</a>设置Kernel类型为KERNEL_TYPE_MIX_xxx，同时启用AIV核和AIC核。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define ASCENDC_CUBE_ONLY</span><span> // 指定Matmul运行在AIC上</span></span>
<span class="line"><span>KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2);  // 设置Kernel类型为KERNEL_TYPE_MIX_xxx</span></span>
<span class="line"><span>if ASCEND_IS_AIC {</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    // AIC核进行Matmul计算</span></span>
<span class="line"><span>    // AIC核完成计算后，通过AscendC::CrossCoreSetFlag&lt;modeId, pipe&gt;(flagId)发送同步flag</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>if ASCEND_IS_AIV {</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    // AIV核通过AscendC::CrossCoreWaitFlag(flagId)接收同步flag</span></span>
<span class="line"><span>    // AIV核进行LeakyRelu计算</span></span>
<span class="line"><span>}</span></span></code></pre></div>完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_fused_mannul" target="_blank" rel="noreferrer">BareMix样例</a>。</li></ul></div>`,30)])])}const _=t(g,[["render",d]]);export{C as __pageData,_ as default};
